            try c.sendMoney(address(c), amount) { reverted = false; } catch { reverted = true; }
        }
        assert(reverted == (amount > balBefore) && (!reverted || true));
        if (!reverted) {
            assert(address(c).balance == balBefore && c.depositsCount() == depBefore + 2);
        }
    }
